import ctypes
import mmap as stdmmap


libc = ctypes.CDLL(None)

# void *mmap(void *addr, size_t length, int prot,
#            int flags, int fd, off_t offset);
libc.mmap.argtypes = [
    ctypes.c_void_p,
    ctypes.c_size_t,
    ctypes.c_int,
    ctypes.c_int,
    ctypes.c_int,
    ctypes.c_long,
]
libc.mmap.restype = ctypes.c_void_p

# int munmap(void *addr, size_t length);
libc.munmap.argtypes = [
    ctypes.c_void_p,
    ctypes.c_size_t,
]
libc.munmap.restype = ctypes.c_int


def mmap(
    fileno: int,
    length: int,
    flags: int = stdmmap.MAP_SHARED,
    prot: int = stdmmap.PROT_READ | stdmmap.PROT_WRITE,
    offset: int = 0,
) -> int:
    """
    Map a file descriptor with libc.mmap() and return a writable memoryview.

    Unlike Python's mmap.mmap(), this calls libc directly and therefore
    bypasses Python-side checks such as rejecting a mapping whose length is
    greater than the file's reported size. This is useful for special files
    such as some procfs/sysfs/device mappings.
    """
    return libc.mmap(None, length, prot, flags, fileno, offset)


def mmap_memoryview(addr: int, length: int) -> memoryview:
    """
    Create a memoryview referring to an existing memory region.

    Args:
        addr:
            Address of the memory region.

        length:
            Length of the memory region in bytes.

    Returns:
        A byte-oriented memoryview referring directly to the memory region.

        Indexing returns integers::

            view[0]

        Slicing returns another memoryview::

            view[0:32]

        Convert a slice to bytes when needed::

            view[0:32].tobytes()

        Writes modify the memory directly::

            view[0] = 0x12
            view[0:4] = b"abcd"

    Notes:
        The returned memoryview does not own the underlying memory. It must
        not be accessed after the underlying memory has been freed or unmapped.

        Any derived memoryviews, such as view[0:32], must also not be used
        after the underlying memory has been freed or unmapped.
    """
    buffer = (ctypes.c_ubyte * length).from_address(addr)

    # ctypes may expose the buffer using a format such as "<B".
    # Cast it to a regular byte-oriented memoryview.
    return memoryview(buffer).cast("B")


def munmap(view: memoryview) -> None:
    """
    Unmap memory previously returned by mmap().

    The view and all derived views become invalid after this call.
    """
    addr = ctypes.addressof(ctypes.c_ubyte.from_buffer(view))
    length = view.nbytes

    view.release()
    libc.munmap(addr, length)
